import { Inngest, NonRetriableError, RetryAfterError } from "inngest";

const inngest = new Inngest({ id: "billing-app" });

export const processInvoice = inngest.createFunction(
  { id: "process-invoice", triggers: { event: "billing/invoice.created" }, retries: 4 },
  async ({ event, step }) => {
    if (!event.data.invoiceId) {
      throw new NonRetriableError("invoiceId is required");
    }

    return step.run("save-invoice", async () => {
      const response = await fetch(`/api/invoices/${event.data.invoiceId}`);
      if (response.status === 429) {
        throw new RetryAfterError("rate limited", "30s");
      }
      if (!response.ok) throw new Error(`HTTP ${response.status}`);
      return response.json();
    });
  },
);

